/**
 * 词库管理页。
 *
 * - 顶部：标题栏 + 搜索输入框
 * - 主体：LazyColumn 展示词条；每项 ≤ 56dp
 * - 交互：左右滑删除（SwipeToDismiss）、FAB 新增、空态提示
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DictionaryScreen(viewModel: DictionaryViewModel) {
    val query by viewModel.searchQuery.collectAsState()
    val items by viewModel.filteredWords.collectAsState()

    var showAddDialog by remember { mutableStateOf(false) }

    Scaffold(
        topBar = {
            CenterAlignedTopAppBar(
                title = { Text(text = stringResource(id = R.string.dictionary_title)) }
            )
        },
        floatingActionButton = {
            FloatingActionButton(onClick = { showAddDialog = true }) {
                Text(text = "＋", fontSize = 22.sp)
            }
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
        ) {
            OutlinedTextField(
                value = query,
                onValueChange = viewModel::search,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 8.dp),
                placeholder = { Text(text = stringResource(id = R.string.search_hint)) },
                singleLine = true
            )

            if (items.isEmpty()) {
                EmptyState()
            } else {
                LazyColumn(modifier = Modifier.fillMaxSize()) {
                    items(items = items, key = { it.id }) { entity ->
                        DismissibleRow(
                            word = entity,
                            onDelete = { viewModel.deleteWord(entity.id) }
                        )
                        Divider()
                    }
                }
            }
        }
    }

    if (showAddDialog) {
        AddWordDialog(
            onDismiss = { showAddDialog = false },
            onConfirm = { new ->
                viewModel.addWord(new)
                showAddDialog = false
            }
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun DismissibleRow(
    word: WordEntity,
    onDelete: () -> Unit
) {
    val state = rememberDismissState(
        confirmValueChange = { value ->
            if (value == DismissValue.DismissedToStart || value == DismissValue.DismissedToEnd) {
                onDelete()
                true
            } else false
        }
    )
    SwipeToDismiss(
        state = state,
        directions = setOf(DismissDirection.EndToStart, DismissDirection.StartToEnd),
        background = {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 56.dp)
                    .padding(horizontal = 16.dp),
                contentAlignment = Alignment.CenterEnd
            ) {
                Text(
                    text = "✕",
                    color = Color(0xFFB00020),
                    fontSize = 20.sp
                )
            }
        },
        dismissContent = { WordRow(word = word) }
    )
}

@Composable
private fun WordRow(word: WordEntity) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(max = 56.dp)
            .padding(horizontal = 16.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Text(
            text = word.word,
            style = MaterialTheme.typography.headlineSmall,
            fontWeight = FontWeight.Medium,
            modifier = Modifier.weight(1f)
        )
        Text(
            text = word.meaning.orEmpty(),
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.weight(1.4f)
        )
    }
}

@Composable
private fun EmptyState() {
    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = stringResource(id = R.string.empty_dictionary),
            color = MaterialTheme.colorScheme.onSurfaceVariant
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun AddWordDialog(
    onDismiss: () -> Unit,
    onConfirm: (WordEntity) -> Unit
) {
    var word by remember { mutableStateOf("") }
    var pinyin by remember { mutableStateOf("") }
    var meaning by remember { mutableStateOf("") }
    var category by remember { mutableStateOf("常用") }

    // 词条 word 字段变空时自动清理其它输入的引导（保持轻量，不做校验）
    LaunchedEffect(word) { /* no-op：保留 hook 供后续校验 */ }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(text = stringResource(id = R.string.add_word)) },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                OutlinedTextField(
                    value = word,
                    onValueChange = { word = it },
                    label = { Text(text = "柯尔克孜语") },
                    singleLine = true
                )
                OutlinedTextField(
                    value = pinyin,
                    onValueChange = { pinyin = it },
                    label = { Text(text = "拼读") },
                    singleLine = true
                )
                OutlinedTextField(
                    value = meaning,
                    onValueChange = { meaning = it },
                    label = { Text(text = "释义") },
                    singleLine = true
                )
                OutlinedTextField(
                    value = category,
                    onValueChange = { category = it },
                    label = { Text(text = "分类") },
                    singleLine = true
                )
            }
        },
        confirmButton = {
            TextButton(
                enabled = word.isNotBlank(),
                onClick = {
                    onConfirm(
                        WordEntity(
                            word = word.trim(),
                            pinyin = pinyin.trim().ifEmpty { null },
                            meaning = meaning.trim().ifEmpty { null },
                            category = category.trim().ifEmpty { "常用" }
                        )
                    )
                }
            ) { Text(text = stringResource(id = R.string.done)) }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text(text = stringResource(id = R.string.delete_confirm_cancel))
            }
        }
    )

    Spacer(modifier = Modifier.height(0.dp))
}